ls -a; cat .gitlab-ci.yml 2>/dev/null; xping report --test InvoiceExporter_ExportsBatch_WithinTimeBudget --json 2>/dev/null | python3 -I -c "
import json,sys,collections
d=json.load(sys.stdin)
def find(o):
    if isinstance(o,list):
        if o and isinstance(o[0],dict) and any('runner' in str(v) for v in o[0].values()): yield o
        for x in o: yield from find(x)
    elif isinstance(o,dict):
        for v in o.values(): yield from find(v)
for runs in find(d):
    print(len(runs), runs[0])
    c=collections.Counter()
    for r in runs: c[tuple(str(v) for v in r.values() if 'runner' in str(v) or str(v).lower() in('passed','failed'))]+=1
    for k,v in sorted(c.items()): print(k,v)
    break
"; git remote -v; which glab
